namespace ElectronicRegisterAPI.Domain.DTOs;

/// <summary>All-or-nothing creation of manual grades for one class-subject and date.</summary>
public class CreateGradeBatchDto
{
    /// <summary>Generated by the client once per submission; replays return the first response.</summary>
    public Guid EventId { get; set; }
    /// <summary>Alternative to SubjectId (+ ClassId): identifies the class-subject directly.</summary>
    public Guid? ClassSubjectId { get; set; }
    public Guid? SubjectId { get; set; }
    /// <summary>Optional when the subject identifies a single class-subject visible to the caller.</summary>
    public Guid? ClassId { get; set; }
    public DateOnly Date { get; set; }
    public string? Description { get; set; }
    public List<GradeBatchItemDto>? Grades { get; set; }
}
